mapper.select:
IF EXISTS (
    SELECT 1
    FROM AutoNumber
    WHERE DocName = #{docName}
      AND DocDate = #{docDate}
)
    UPDATE AutoNumber
    SET Seq = Seq + 1
    OUTPUT INSERTED.Seq
    WHERE DocName = #{docName}
      AND DocDate = #{docDate}
ELSE
    INSERT INTO AutoNumber (DocName, DocDate, Seq)
    OUTPUT INSERTED.Seq
    VALUES (#{docName}, #{docDate}, 1)
